      "codigo_refatorado": "using UnityEngine;
using UnityEngine.Rendering;

public class DynamicResolutionAndGpuManager : MonoBehaviour
{
    [Header("Limites de Render Scale")]
    [Range(0.5f, 1.0f)] public float minRenderScale = 0.65f;
    [Range(0.5f, 1.0f)] public float maxRenderScale = 1.0f;

    [Header("Alvo e Sensibilidade")]
    public float targetFrameTimeMs = 16.0f;
    public float adjustmentSpeed = 0.05f;
    public float evaluationInterval = 0.25f;

    private float _timeSinceLastEval = 0.0f;
    private float _currentRenderScale = 1.0f;
    private FrameTiming[] _frameTimings = new FrameTiming[1];

    private void Start()
    {
        _currentRenderScale = maxRenderScale;
        ScalableBufferManager.ResizeBuffers(_currentRenderScale, _currentRenderScale);
    }

    private void Update()
    {
        _timeSinceLastEval += Time.unscaledDeltaTime;
        if (_timeSinceLastEval < evaluationInterval)
        {
            return;
        }
        _timeSinceLastEval = 0.0f;

        FrameTimingManager.CaptureFrameTimings();
        uint captured = FrameTimingManager.GetLatestTimings(1, _frameTimings);

        if (captured > 0)
        {
            double gpuTimeMs = _frameTimings[0].gpuFrameTime;
            if (gpuTimeMs <= 0.0)
            {
                gpuTimeMs = Time.unscaledDeltaTime * 1000.0f;
            }

            if (gpuTimeMs > targetFrameTimeMs)
            {
                _currentRenderScale = Mathf.Max(minRenderScale, _currentRenderScale - adjustmentSpeed);
            }
            else if (gpuTimeMs < targetFrameTimeMs * 0.85f)
            {
                _currentRenderScale = Mathf.Min(maxRenderScale, _currentRenderScale + adjustmentSpeed);
            }

            ScalableBufferManager.ResizeBuffers(_currentRenderScale, _currentRenderScale);
        }
    }
}",
